declare(strict_types=1);

namespace App\Tests\Integration;

use App\Modules\Contracts\Application\ContractService;
use App\Modules\Contracts\Domain\Contract;
use App\Modules\Contracts\Domain\ContractStatus;
use App\Modules\Contracts\Infrastructure\ContractActivityProjector;
use App\Modules\Contracts\Infrastructure\ContractsConnector;
use App\Modules\Contracts\Infrastructure\GenerateContractsReportJob;
use App\Modules\Contracts\Infrastructure\PurgeDeletedContractsJob;
use App\Platform\Identity\Domain\User;
use App\Platform\Identity\Infrastructure\UserRepository;
use App\Platform\Integrations\Exception\IntegrationException;
use App\Platform\Messaging\EventEnvelope;
use App\Platform\Queue\JobContext;
use App\Platform\Storage\ObjectStorage;
use App\Shared\Domain\Exception\AccessDeniedException;
use App\Shared\Domain\Exception\ConflictException;
use App\Shared\Domain\Exception\NotFoundException;
use App\Shared\Domain\Exception\ValidationException;
use App\Shared\Infrastructure\Database\Sql;
use App\Tests\Support\Fixtures;
use Yiisoft\Db\Query\Query;

/**
 * ContractService against the real test database: audit + outbox in one transaction, tenant isolation,
 * optimistic locking, RBAC, soft delete and the generated jobs / consumer / connector.
 */
final class ContractsServiceTest extends IntegrationTestCase
{
    private ContractService $service;
    private User $admin;
    private User $member;
    private User $foreignAdmin;
    private string $foreignTenant;

    protected function setUp(): void
    {
        parent::setUp();
        $this->service = $this->get(ContractService::class);
        $this->foreignTenant = (string) $this->db->createCommand(
            "INSERT INTO tenants (code, name) VALUES (:c, 'Foreign test tenant') RETURNING id",
            [':c' => 't-' . bin2hex(random_bytes(4))],
        )->queryScalar();
        $this->admin = $this->user(Fixtures::user(['business_admin']));
        $this->member = $this->user(Fixtures::user(['user']));
        $this->foreignAdmin = $this->user(Fixtures::user(['business_admin'], extra: ['tenant_id' => $this->foreignTenant]));
    }

    public function testCreateWritesRowAndAuditAtomically(): void
    {
        $e = $this->service->create($this->admin, $this->input());
        self::assertSame(1, $e->version());
        self::assertSame($this->admin->tenantId, $e->tenantId);
        self::assertTrue((new Query($this->db))->from('audit_log')->where(['entity_type' => 'contract', 'entity_id' => $e->id, 'action' => 'contract.created'])->exists());
        $outbox = (new Query($this->db))->from('outbox')->where(['aggregate_id' => $e->id])->all();
        self::assertCount(1, $outbox);
        self::assertSame('contracts.events', $outbox[0]['topic']);
        self::assertSame(Contract::EVENT_CREATED, $outbox[0]['event_type']);

        // one transaction: rolling back the outer transaction removes row, audit and event
        $tx = $this->db->beginTransaction();
        $rolled = $this->service->create($this->admin, $this->input());
        $tx->rollBack();
        self::assertFalse((new Query($this->db))->from('contracts')->where(['id' => $rolled->id])->exists());
        self::assertFalse((new Query($this->db))->from('outbox')->where(['aggregate_id' => $rolled->id])->exists());
    }

    public function testValidationErrorsArePerField(): void
    {
        try {
            $this->service->create($this->admin, []);
            self::fail('ValidationException expected');
        } catch (ValidationException $e) {
            foreach (['title'] as $field) {
                self::assertArrayHasKey($field, $e->errors(), $field);
            }
        }
    }

    public function testTenantIsolationReportsForeignRecordsAsNotFound(): void
    {
        $e = $this->service->create($this->admin, $this->input());
        try {
            $this->service->get($this->foreignAdmin, $e->id);
            self::fail('foreign tenant could read the record');
        } catch (NotFoundException) {
        }
        $this->expectException(NotFoundException::class);
        $this->service->update($this->foreignAdmin, $e->id, [], 1);
    }

    public function testSearchIsTenantScoped(): void
    {
        $input = $this->input();
        $this->service->create($this->foreignAdmin, $input);
        self::assertSame(0, $this->service->search($this->admin, ['q' => $input['title']], 1, 50, null)->total);
        self::assertSame(1, $this->service->search($this->foreignAdmin, ['q' => $input['title']], 1, 50, null)->total);
    }

    public function testOptimisticLocking(): void
    {
        $e = $this->service->create($this->admin, $this->input());
        $value = 'Updated title ' . bin2hex(random_bytes(4));
        $v2 = $this->service->update($this->admin, $e->id, ['title' => $value], 1);
        self::assertSame(2, $v2->version());
        try {
            $this->service->update($this->admin, $e->id, ['title' => $value], 1);
            self::fail('stale write accepted');
        } catch (ConflictException $ex) {
            self::assertSame('stale_version', $ex->errorCode());
        }
        self::assertSame(2, $this->service->get($this->admin, $e->id)->version());
    }

    public function testPermissionsAreEnforced(): void
    {
        $this->expectException(AccessDeniedException::class);
        $this->service->create($this->member, $this->input());
    }

    public function testStatusTransitions(): void
    {
        $e = $this->service->create($this->admin, ['owner_id' => $this->member->id] + $this->input());
        self::assertSame(ContractStatus::initial(), $e->status());
        $next = $this->service->changeStatus($this->admin, $e->id, ContractStatus::Active->value, 1, 'go');
        self::assertSame(ContractStatus::Active, $next->status());
        self::assertSame(2, $next->version());
        self::assertTrue((new Query($this->db))->from('outbox')->where(['aggregate_id' => $e->id, 'event_type' => Contract::EVENT_STATUS_CHANGED])->exists());
        self::assertGreaterThanOrEqual(1, (int) (new Query($this->db))->from('notifications')
            ->where(['user_id' => $this->member->id, 'template_code' => 'contract.status_changed'])->count(), 'referenced user notified');
        $instance = (new Query($this->db))->select('i.state')->from(['i' => 'workflow_instances'])->innerJoin(['w' => 'workflows'], 'w.id = i.workflow_id')
            ->where(['w.code' => 'contract.lifecycle', 'i.entity_id' => $e->id])->scalar();
        if ($instance !== false && $instance !== null) {
            self::assertSame(ContractStatus::Active->value, $instance, 'workflow instance mirrors the state');
        }
        try {
            $this->service->changeStatus($this->admin, $e->id, ContractStatus::initial()->value);
            self::fail('backwards transition accepted');
        } catch (ConflictException $ex) {
            self::assertSame('invalid_transition', $ex->errorCode());
        }
        $this->expectException(ValidationException::class);
        $this->service->changeStatus($this->admin, $e->id, 'bogus');
    }

    public function testDeleteIsSoftAndHidesTheRecord(): void
    {
        $e = $this->service->create($this->admin, $this->input());
        $this->service->delete($this->admin, $e->id, 1);
        self::assertNotNull((new Query($this->db))->select('deleted_at')->from('contracts')->where(['id' => $e->id])->scalar());
        self::assertTrue((new Query($this->db))->from('outbox')->where(['aggregate_id' => $e->id, 'event_type' => Contract::EVENT_DELETED])->exists());
        $this->expectException(NotFoundException::class);
        $this->service->get($this->admin, $e->id);
    }

    public function testConsumerBuildsTheReadModelIdempotently(): void
    {
        $e = $this->service->create($this->admin, $this->input());
        $row = (new Query($this->db))->from('outbox')->where(['aggregate_id' => $e->id])->one();
        self::assertNotNull($row);
        $envelope = new EventEnvelope((string) $row['id'], (string) $row['event_type'], 1, (string) $row['aggregate_type'], (string) $row['aggregate_id'],
            Sql::json($row['payload']), date(DATE_ATOM), null, $e->tenantId, $this->admin->id);
        $projector = $this->get(ContractActivityProjector::class);
        $projector->handle($envelope);
        $projector->handle($envelope); // replay
        self::assertSame(1, (int) (new Query($this->db))->from('contract_activity')->where(['entity_id' => $e->id])->count());
        $activity = $this->service->activity($this->admin, $e->id);
        self::assertSame('read_model', $activity['source']);
        self::assertStringContainsString('created', $activity['items'][0]['summary']);
    }

    public function testCleanupJobPurgesOldDeletedRows(): void
    {
        $old = $this->service->create($this->admin, $this->input());
        $fresh = $this->service->create($this->admin, $this->input());
        $this->service->delete($this->admin, $old->id);
        $this->service->delete($this->admin, $fresh->id);
        $this->db->createCommand("UPDATE contracts SET deleted_at = now() - interval '100 days' WHERE id = :id", [':id' => $old->id])->execute();
        $this->get(PurgeDeletedContractsJob::class)->handle(['retention_days' => 90], $this->context('contracts.cleanup'));
        self::assertFalse((new Query($this->db))->from('contracts')->where(['id' => $old->id])->exists(), 'old deleted row purged');
        self::assertTrue((new Query($this->db))->from('contracts')->where(['id' => $fresh->id])->exists(), 'recently deleted row kept');
    }

    public function testReportJobWritesCsvToObjectStorage(): void
    {
        $storage = $this->get(ObjectStorage::class);
        if (!$storage->isConfigured()) {
            self::markTestSkipped('Object storage: Not configured.');
        }
        $this->service->create($this->admin, $this->input());
        $r = $this->service->requestReport($this->admin);
        $this->get(GenerateContractsReportJob::class)->handle(['report_id' => $r['report_id']], $this->context('contracts.report.generate'));
        $report = $this->service->report($this->admin, $r['report_id']);
        self::assertSame('done', $report['status'], (string) $report['error']);
        self::assertGreaterThanOrEqual(1, (int) $report['rows_count']);
        $csv = $storage->filesystem()->read((string) $report['path']);
        self::assertStringStartsWith("\xEF\xBB\xBF", $csv);
        self::assertStringContainsString('created_at', $csv);
    }

    public function testConnectorIsNotConfiguredUntilAnOperatorEnablesIt(): void
    {
        $connector = $this->get(ContractsConnector::class);
        self::assertFalse($connector->isConfigured());
        $e = $this->service->create($this->admin, $this->input());
        $this->expectException(IntegrationException::class);
        $connector->push($e);
    }

    /** @return array<string,mixed> valid input (random values keep runs independent) */
    private function input(): array
    {
        return [
            'title' => 'Sample title ' . bin2hex(random_bytes(4)),
            'amount' => '1250.50',
            'due_on' => '2026-12-31',
        ];
    }

    private function user(array $fixture): User
    {
        $user = $this->get(UserRepository::class)->find($fixture['id']);
        self::assertNotNull($user);
        return $user;
    }
    private function context(string $type): JobContext
    {
        return new JobContext('test-' . bin2hex(random_bytes(4)), $type, 1, null, static fn(): bool => false, static fn(int $p): null => null);
    }
}
